# Generated by manage.py generate_test_cases.
"""Object-prefilled calendar composition through the existing event form."""

import json
from typing import Any
from unittest.mock import patch

from django.contrib.auth import get_user_model
from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse
from django.utils import timezone

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.models.communication.email_account import EmailAccount
from bloomerp.models.communication.inbox.inbox_folder import InboxFolder
from bloomerp.permissions.definition import RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestInviteForObjectComponentViewComponent(
    InboxCalendarFixtures, BloomerpComponentTestCase
):
    """Preserve source permissions, calendar validation, delivery, and modal completion."""

    view_name = "components_calendar_invite_for_object"

    def extendedSetup(self) -> None:
        """Provide a readable contact, an accessible calendar, and a possible invitation sender."""
        self.prepare_calendar()
        self.owner.email = "contact@example.com"
        self.owner.save(update_fields=["email"])
        self.contact_query = {
            "content_type_id": str(
                ContentType.objects.get_for_model(get_user_model()).pk
            ),
            "object_id": str(self.owner.pk),
            "email_field": "email",
        }
        self.sender = EmailAccount.objects.create(
            email_address="sender@example.com", status="active"
        )
        InboxFolder.objects.create(
            inbox=self.source, type="email", related_object_id=str(self.sender.pk)
        )

    def event_data(self, **overrides: Any) -> dict[str, Any]:
        """Build a valid shared-composer submission without contacting SMTP by default."""
        return {
            "inbox": str(self.source.pk),
            "title": "Contact invitation",
            "event_timezone": timezone.get_current_timezone_name(),
            "start_date": self.today.isoformat(),
            "end_date": self.today.isoformat(),
            "start_time": "10:00",
            "end_time": "11:00",
            "attendees": self.owner.email,
            **overrides,
        }

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise prefilled recipients, denied provenance, validation, and explicit invitation delivery."""
        return [
            RequestScenario(
                name="Login required",
                query_params=self.contact_query,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Malformed source identifiers return a missing-object response",
                user=self.actor,
                query_params={**self.contact_query, "content_type_id": "invalid"},
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Prefills the shared calendar composer",
                user=self.actor,
                query_params=self.contact_query,
                headers={"HX-Request": "true"},
                expected=ExpectedResult(response_validators=self.prefilled_composer),
            ),
            RequestScenario(
                name="Event creation permission is required",
                user=self.owner,
                query_params=self.contact_query,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Unreadable contact field is denied",
                user=self.owner,
                query_params=self.contact_query,
                prepare=self.grant_without_contact_email,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="A different field cannot be used as an email address",
                user=self.actor,
                query_params={**self.contact_query, "email_field": "first_name"},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Invalid submission keeps the same composer open",
                method="POST",
                user=self.actor,
                query_params=self.contact_query,
                data=self.event_data(title=""),
                headers={"HX-Request": "true"},
                expected=ExpectedResult(response_validators=self.invalid_composer),
            ),
            RequestScenario(
                name="Saving closes only the contact calendar dialog",
                method="POST",
                user=self.actor,
                query_params=self.contact_query,
                data=self.event_data(),
                headers={"HX-Request": "true"},
                expected=ExpectedResult(response_validators=self.saved_composer),
            ),
            RequestScenario(
                name="Email invitations reuse the existing delivery service",
                method="POST",
                user=self.actor,
                query_params=self.contact_query,
                data=self.event_data(sender=str(self.sender.pk), send_invitations="on"),
                prepare=self.mock_delivery,
                headers={"HX-Request": "true"},
                expected=ExpectedResult(response_validators=self.delivered_invitation),
            ),
            RequestScenario(
                name="POST rechecks contact-field permission",
                method="POST",
                user=self.owner,
                query_params=self.contact_query,
                data=self.event_data(),
                prepare=self.grant_without_contact_email,
                expected=ExpectedResult(status_code=403),
            ),
        ]

    def grant_without_contact_email(self, _scenario: RequestScenario) -> None:
        """Grant calendar creation and contact rows while withholding their email addresses."""
        PolicyManager.create_policy(
            CalendarEvent,
            global_permissions=["add"],
            field_permissions={"__all__": ["add"]},
            row_permissions=[RowPolicyRuleContent(permissions=["add"], conditions=[])],
        ).assign_user(self.owner)
        PolicyManager.create_policy(
            get_user_model(),
            global_permissions=["view"],
            field_permissions={"first_name": ["view"]},
            row_permissions=[RowPolicyRuleContent(permissions=["view"], conditions=[])],
        ).assign_user(self.owner)

    def mock_delivery(self, _scenario: RequestScenario) -> None:
        """Observe the actual composer's invitation handoff without sending external mail."""
        self.delivery = self.enterContext(
            patch(
                "bloomerp.communication.calendar.outgoing.send_calendar_request",
                return_value=1,
            )
        )

    def prefilled_composer(self, response: HttpResponse) -> bool:
        """Keep recipient chips, availability, and the object-scoped form action together."""
        return (
            response.context["form"].initial["attendees"] == self.owner.email
            and "components/communication/calendar/invite-for-object/"
            in response.context["form_url"]
            and "email_field=email" in response.context["form_url"]
            and 'bloomerp-component="calendar-event-editor"'
            in response.content.decode()
            and 'bloomerp-component="calendar-availability"'
            in response.content.decode()
        )

    def invalid_composer(self, response: HttpResponse) -> bool:
        """Preserve errors and source context without closing the dialog or creating an event."""
        return (
            self.prefilled_composer(response)
            and bool(response.context["form"].errors)
            and "HX-Trigger" not in response
            and not CalendarEvent.objects.filter(title="Contact invitation").exists()
        )

    def saved_composer(self, response: HttpResponse) -> bool:
        """Save the event through existing services and complete the owning modal only."""
        event = CalendarEvent.objects.get(title="Contact invitation")
        return (
            event.participants.filter(email=self.owner.email).exists()
            and event.inboxes.filter(pk=self.source.pk).exists()
            and json.loads(response["HX-Trigger"])
            == {"bloomerp:close-modal": {"modalId": "detail-calendar-modal"}}
            and "Location" not in response
            and "HX-Refresh" not in response
            and 'data-message-text="Event created."' in response.content.decode()
        )

    def delivered_invitation(self, response: HttpResponse) -> bool:
        """Verify explicit sending uses the selected existing email account."""
        self.delivery.assert_called_once()
        return (
            self.saved_composer(response)
            and self.delivery.call_args.kwargs["email_account_id"] == self.sender.pk
        )
